export function decodeMetricsApiError(
    error: ApiError<unknown>,
): ApiError<unknown> {
    switch (error.errorCode) {
        case "ACCESS_DENIED":
            return new AccessDeniedError(error);
        case "ACCOUNT_NOT_ACTIVE":
            return new AccountNotActiveError(error);
        case "ALARM_DATAPOINTS_EXCEED_EVALUATION_BUCKETS":
            return new AlarmDatapointsExceedEvaluationBucketsError(error);
        case "ALARM_EVALUATION_PERIOD_NOT_MULTIPLE_OF_RESOLUTION":
            return new AlarmEvaluationPeriodNotMultipleOfResolutionError(error);
        case "ALARM_EVALUATION_WINDOW_TOO_LARGE":
            return new AlarmEvaluationWindowTooLargeError(error);
        case "CHARTS_OVERLAP":
            return new ChartsOverlapError(error);
        case "CHART_COLUMN_INVALID":
            return new ChartColumnInvalidError(error);
        case "CHART_COL_SPAN_INVALID":
            return new ChartColSpanInvalidError(error);
        case "CHART_EXCEEDS_DASHBOARD_WIDTH":
            return new ChartExceedsDashboardWidthError(error);
        case "CHART_ROW_INVALID":
            return new ChartRowInvalidError(error);
        case "CHART_ROW_SPAN_INVALID":
            return new ChartRowSpanInvalidError(error);
        case "CHART_VARIABLE_TYPE_REQUIRED":
            return new ChartVariableTypeRequiredError(error);
        case "CHART_VARIABLE_VISIBLE_REQUIRED":
            return new ChartVariableVisibleRequiredError(error);
        case "CONTRADICTORY_DASHBOARD_FILTER":
            return new ContradictoryDashboardFilterError(error);
        case "CYCLIC_DASHBOARD_VARIABLE_DEPENDENCY":
            return new CyclicDashboardVariableDependencyError(error);
        case "DASHBOARD_REFRESH_INTERVAL_REQUIRED":
            return new DashboardRefreshIntervalRequiredError(error);
        case "DASHBOARD_REFRESH_INTERVAL_TOO_FAST":
            return new DashboardRefreshIntervalTooFastError(error);
        case "DUPLICATE_ALARM_VARIABLE_NAME":
            return new DuplicateAlarmVariableNameError(error);
        case "DUPLICATE_CHART_ID":
            return new DuplicateChartIdError(error);
        case "DUPLICATE_CHART_VARIABLE_NAME":
            return new DuplicateChartVariableNameError(error);
        case "DUPLICATE_DASHBOARD_FILTER":
            return new DuplicateDashboardFilterError(error);
        case "DUPLICATE_DIMENSION_NAME":
            return new DuplicateDimensionNameError(error);
        case "EMAIL_NOTIFICATION_CHANNEL_CANNOT_INCLUDE_WEBHOOK_CONFIG":
            return new EmailNotificationChannelCannotIncludeWebhookConfigError(
                error,
            );
        case "EMAIL_NOTIFICATION_CHANNEL_CONFIG_REQUIRED":
            return new EmailNotificationChannelConfigRequiredError(error);
        case "ENTRY_REQUIRES_VALUE_OR_STATISTIC_SET":
            return new EntryRequiresValueOrStatisticSetError(error);
        case "ENTRY_TIMESTAMP_IN_FUTURE":
            return new EntryTimestampInFutureError(error);
        case "ENTRY_TIMESTAMP_TOO_OLD":
            return new EntryTimestampTooOldError(error);
        case "EXPRESSION_TOO_COMPLEX":
            return new ExpressionTooComplexError(error);
        case "EXPRESSION_VARIABLE_EXPRESSION_REQUIRED":
            return new ExpressionVariableExpressionRequiredError(error);
        case "INVALID_AGGREGATION":
            return new InvalidAggregationError(error);
        case "INVALID_ALARM_REQUEST":
            return new InvalidAlarmRequestError(error);
        case "INVALID_DASHBOARD_FILTER":
            return new InvalidDashboardFilterError(error);
        case "INVALID_DASHBOARD_TIME_RANGE":
            return new InvalidDashboardTimeRangeError(error);
        case "INVALID_EXPRESSION":
            return new InvalidExpressionError(error);
        case "INVALID_EXPRESSION_TOKEN":
            return new InvalidExpressionTokenError(error);
        case "INVALID_METRIC_DATA":
            return new InvalidMetricDataError(error);
        case "INVALID_METRIC_QUERY":
            return new InvalidMetricQueryError(error);
        case "INVALID_NUMERIC_EXPRESSION":
            return new InvalidNumericExpressionError(error);
        case "INVALID_OR_EXPIRED_VERIFICATION_CODE":
            return new InvalidOrExpiredVerificationCodeError(error);
        case "INVALID_PAGINATION_TOKEN":
            return new InvalidPaginationTokenError(error);
        case "METRIC_QUERY_TIMESTAMP_IN_FUTURE":
            return new MetricQueryTimestampInFutureError(error);
        case "METRIC_QUERY_TIMESTAMP_TOO_OLD":
            return new MetricQueryTimestampTooOldError(error);
        case "METRIC_VARIABLE_METRIC_NAME_REQUIRED":
            return new MetricVariableMetricNameRequiredError(error);
        case "MISMATCHED_EXPRESSION_PARENTHESES":
            return new MismatchedExpressionParenthesesError(error);
        case "MISSING_EXPRESSION_OPERAND":
            return new MissingExpressionOperandError(error);
        case "MISSING_EXPRESSION_OPERANDS":
            return new MissingExpressionOperandsError(error);
        case "NOTIFICATION_CHANNEL_CONFIG_REQUIRED":
            return new NotificationChannelConfigRequiredError(error);
        case "NOTIFICATION_CHANNEL_IN_USE":
            return new NotificationChannelInUseError(error);
        case "ONLY_EMAIL_NOTIFICATION_CHANNELS_CAN_BE_VERIFIED":
            return new OnlyEmailNotificationChannelsCanBeVerifiedError(error);
        case "RESOURCE_DELETION_IN_PROGRESS":
            return new ResourceDeletionInProgressError(error);
        case "RESOURCE_LIMIT_EXCEEDED":
            return new ResourceLimitExceededError(error);
        case "RESOURCE_NOT_FOUND":
            return new ResourceNotFoundError(error);
        case "RESOURCE_UPDATED_CONCURRENTLY":
            return new ResourceUpdatedConcurrentlyError(error);
        case "START_TIME_AFTER_END_TIME":
            return new StartTimeAfterEndTimeError(error);
        case "STATISTIC_SET_INCOMPLETE":
            return new StatisticSetIncompleteError(error);
        case "STATISTIC_SET_INVALID_RANGE":
            return new StatisticSetInvalidRangeError(error);
        case "TOKEN_EXPIRED":
            return new TokenExpiredError(error);
        case "TOO_MANY_DIMENSIONS":
            return new TooManyDimensionsError(error);
        case "TOO_MANY_DIMENSION_COMBINATIONS":
            return new TooManyDimensionCombinationsError(error);
        case "UNAUTHORIZED":
            return new UnauthorizedError(error);
        case "UNSUPPORTED_CHART_VARIABLE_TYPE":
            return new UnsupportedChartVariableTypeError(error);
        case "UNVERIFIED_NOTIFICATION_CHANNEL":
            return new UnverifiedNotificationChannelError(error);
        case "WEBHOOK_NOTIFICATION_CHANNEL_CANNOT_INCLUDE_EMAIL_CONFIG":
            return new WebhookNotificationChannelCannotIncludeEmailConfigError(
                error,
            );
        case "WEBHOOK_NOTIFICATION_CHANNEL_CONFIG_REQUIRED":
            return new WebhookNotificationChannelConfigRequiredError(error);
        default:
            return error;
    }
}
